/**
 * Typed view over the verified-ledger artifact.
 *
 * The JSON is GENERATED by scripts/verify-ledger.ts straight from Neon
 * (picks + games + pick_settlement_events + pick_proof_receipts). /record and
 * /calibration render only this artifact - never hardcoded numbers. Re-run
 * `npm run verify:ledger` to refresh it; the pages pick it up at build time.
 */

import raw from "./verified-ledger.json";

export interface VerifiedWlp {
  readonly wins: number;
  readonly losses: number;
  readonly pushes: number;
  readonly settled: number;
}

export interface VerifiedLedger {
  readonly schemaVersion: string;
  readonly generatedAt: string;
  readonly source: {
    readonly transport: string;
    readonly tables: readonly string[];
    readonly readOnly: boolean;
  };
  readonly scope: {
    readonly pipelineLedger: string;
    readonly officialRecord: string;
    readonly staking: string;
    readonly clvSign: string;
    readonly calibrationLaw: string;
    readonly commitments: string;
  };
  readonly pipeline: {
    readonly withSettlementEvents: number;
    readonly wlp: VerifiedWlp;
    readonly voided: number;
    readonly pending: number;
    readonly eventResultMismatches: number;
    readonly units: {
      readonly total: number;
      readonly coveredPicks: number;
      readonly missingPricePicks: number;
    };
    readonly clv: {
      readonly graded: number;
      readonly beatClose: number;
      readonly missedClose: number;
      readonly flat: number;
      readonly meanPoints: number | null;
      readonly meanProbability: number | null;
      readonly storedValueMatches: number;
      readonly storedValueMismatches: number;
      readonly mismatchSamples: ReadonlyArray<{
        pickId: string;
        stored: number;
        recomputed: number;
      }>;
    };
  };
  readonly official: {
    readonly wlp: VerifiedWlp;
    readonly units: { readonly total: number; readonly coveredPicks: number };
    readonly confidenceBuckets: ReadonlyArray<{
      label: string;
      min: number;
      max: number;
      count: number;
    }>;
    readonly gate: {
      readonly clvBackedSettled: number;
      readonly target: number;
      readonly unlocked: boolean;
      readonly winRate: number | null;
    };
  };
  readonly commitments: {
    readonly receipts: number;
    readonly hashVerified: number;
    readonly preKickoffVerified: number;
    readonly fullyVerified: number;
    readonly samples: ReadonlyArray<{
      pickId: string;
      contentHash: string;
      frozenAt: string | null;
      kickoff: string | null;
    }>;
    readonly slateCommitments: ReadonlyArray<{
      slateKey: string | null;
      root: string | null;
      count: number | null;
      committedAt: string | null;
    }>;
  };
  readonly recentSettlements: {
    readonly windowHours: number;
    readonly count: number;
    readonly rows: ReadonlyArray<{
      pickId: string;
      matchup: string;
      selection: string;
      line: number | null;
      result: string;
      settledAt: string | null;
      clvVerdict: string | null;
      clvValue: number | null;
      finalScore: string | null;
    }>;
  };
  readonly tnfEvidence:
    | { found: false }
    | {
        found: true;
        pickId: string;
        matchup: string;
        selection: string;
        line: number | null;
        result: string;
        settledAt: string | null;
        clvLockLine: number | null;
        clvCloseLine: number | null;
        clvValue: number | null;
        clvVerdict: string | null;
        finalScore: string | null;
      };
}

export const verifiedLedger = raw as unknown as VerifiedLedger;

/** "79-46-0" - counts only, never a percentage. */
export function formatWlp(wlp: VerifiedWlp): string {
  return `${wlp.wins}-${wlp.losses}-${wlp.pushes}`;
}

/** "+81.47u" / "-295.23u" - signed units, two decimals. */
export function formatUnits(total: number): string {
  const sign = total >= 0 ? "+" : "";
  return `${sign}${total.toFixed(2)}u`;
}

/** Human timestamp for the artifact's verification moment. */
export function formatVerifiedAt(iso: string): string {
  const d = new Date(iso);
  if (!Number.isFinite(d.getTime())) return iso;
  return d.toISOString().replace("T", " ").slice(0, 16) + " UTC";
}